<div class="customer-modal-backdrop" role="presentation"><section class="customer-modal" role="dialog" aria-modal="true"><div class="customer-modal-header"><div><span class="modal-eyebrow"><?= e($purchase['purchase_no']) ?></span><h2>Purchase Details</h2><span class="modal-code"><?= e($purchase['purchase_date']) ?></span></div><a class="customer-modal-close" href="index.php?page=admin&amp;section=stock-purchases">&times;</a></div><div class="customer-modal-body"><div class="modal-detail-grid"><div><span>Supplier</span><strong><?= e($purchase['supplier_name']?:'No supplier') ?></strong></div><div><span>Payment Status</span><strong><?= e(ucfirst($purchase['payment_status']??'paid')) ?></strong></div><div><span>Total Amount</span><strong>Rs. <?= number_format((float)$purchase['total_amount'],2) ?></strong></div><div><span>Paid Amount</span><strong>Rs. <?= number_format((float)($purchase['paid_amount']??0),2) ?></strong></div><div><span>Balance Due</span><strong>Rs. <?= number_format((float)($purchase['balance_amount']??0),2) ?></strong></div><div><span>Created By</span><strong><?= e($purchase['created_by_name']?:'-') ?></strong></div></div><div class="stock-history-section"><h3>Purchase Items</h3><div class="table-responsive"><table class="table admin-table stock-history-table"><thead><tr><th>Part</th><th>Quantity</th><th>Buying Price</th><th>Line Total</th></tr></thead><tbody><?php foreach($purchaseItems as $purchaseItem): ?><tr><td><?= e($purchaseItem['part_code'].' - '.$purchaseItem['part_name']) ?></td><td><?= number_format((float)$purchaseItem['quantity'],2) ?></td><td>Rs. <?= number_format((float)($purchaseItem['buying_price']?:$purchaseItem['unit_cost']),2) ?></td><td>Rs. <?= number_format((float)($purchaseItem['line_total']?:$purchaseItem['amount']),2) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div><div class="customer-modal-footer"><a class="btn btn-light" href="index.php?page=admin&amp;section=stock-purchases">Close</a><a class="btn btn-danger" href="index.php?page=admin&amp;section=stock-purchase-edit&amp;id=<?= (int)$purchase['id'] ?>">Edit</a></div></section></div>
